// ===== 整理待查代碼 =====
// 把待驗證清單裡的代碼去重，一檔只查一次報價

const rows = $input.all().map(i => i.json);

if (!rows.length) {
  console.log('[整理待查代碼] 今日無待驗證項目');
  return [];
}

const symbols = [...new Set(
  rows.map(r => String(r.symbol || '').trim().toUpperCase()).filter(Boolean)
)];

console.log(`[整理待查代碼] 待驗證 ${rows.length} 筆，需查 ${symbols.length} 檔報價`);
console.log('[整理待查代碼] 代碼：', symbols.join(','));

// 護欄：正常情況一天不會超過數十檔，數量爆掉代表 view 或回填出了問題
if (symbols.length > 80) {
  throw new Error(
    `[整理待查代碼] 代碼數 ${symbols.length} 異常偏高，` +
    `請先確認 v_pending_verifications 的內容是否正確`
  );
}

return symbols.map(symbol => ({ json: { symbol } }));

// ===== 計算實績 =====
// 把報價對回待驗證清單，算出各檔在該時間點的報酬率

const quoteItems  = $input.all();
const symbolItems = $('整理待查代碼').all();
const pending     = $('取得待驗證清單').all().map(i => i.json);

// ---------- 用 pairedItem 把報價對回代碼 ----------
const priceBySymbol = {};
const quoteFailed   = [];

quoteItems.forEach((item, idx) => {
  let srcIdx = idx;
  const p = item.pairedItem;
  if (typeof p === 'number') srcIdx = p;
  else if (p && typeof p.item === 'number') srcIdx = p.item;
  else if (Array.isArray(p) && typeof p[0]?.item === 'number') srcIdx = p[0].item;

  const symbol = symbolItems[srcIdx]?.json?.symbol;
  if (!symbol) return;

  const close = Number(item.json?.c);
  if (Number.isFinite(close) && close > 0) priceBySymbol[symbol] = close;
  else quoteFailed.push(symbol);
});

if (pending.length && !Object.keys(priceBySymbol).length) {
  throw new Error(
    `[計算實績] 全部報價取得失敗（共 ${quoteItems.length} 次請求）。` +
    `失敗代碼：${quoteFailed.join(',')}`
  );
}

// ---------- 計算 ----------
const r3 = n => Math.round(n * 1000) / 1000;
const r4 = n => Math.round(n * 10000) / 10000;

const out     = [];
const skipped = [];

for (const row of pending) {
  const symbol = String(row.symbol || '').trim().toUpperCase();
  const price  = priceBySymbol[symbol];
  const entry  = Number(row.entry_price);

  if (!price) {
    skipped.push(`${symbol}/${row.horizon}：無報價`);
    continue;
  }
  if (!Number.isFinite(entry) || entry <= 0) {
    skipped.push(`${symbol}/${row.horizon}：無有效進場價`);
    continue;
  }

  const target = Number(row.target_price);
  const stop   = Number(row.stop_loss);
  const hasTarget = Number.isFinite(target) && target > 0;
  const hasStop   = Number.isFinite(stop)   && stop   > 0;

  out.push({
    json: {
      recommendation_id:    row.recommendation_id,
      horizon:              row.horizon,
      price_then:           r4(price),
      return_pct:           r3(((price - entry) / entry) * 100),
      // 收盤價基準：是「收盤是否已達標」，不是「盤中是否觸及」
      hit_target:           hasTarget ? price >= target : null,
      hit_stop:             hasStop   ? price <= stop   : null,
      elapsed_trading_days: Number(row.elapsed_trading_days) || 0,
      price_basis:          'close',
      source:               'finnhub',
    },
  });
}

console.log(`[計算實績] 產出 ${out.length} 筆 / 待驗證 ${pending.length} 筆`);
if (skipped.length)     console.log('[計算實績] 略過：', skipped.join(' | '));
if (quoteFailed.length) console.log('[計算實績] 報價失敗：', quoteFailed.join(','));

return out;

// ===== 整理 Sheets 更新 =====
// 只更新這次真的有動到的首選標的，避免每天重寫整張表

const touched = new Set(
  $('計算實績').all().map(i => Number(i.json.recommendation_id))
);

const fmt = (v) => {
  const n = Number(v);
  if (!Number.isFinite(n)) return null;
  return `${n > 0 ? '+' : ''}${n.toFixed(2)}%`;
};

const out = [];

for (const item of $input.all()) {
  const r = item.json;
  if (r.role !== 'primary') continue;
  if (!touched.has(Number(r.recommendation_id))) continue;

  const parts = [];
  const f3  = fmt(r.return_3d);
  const f7  = fmt(r.return_7d);
  const f30 = fmt(r.return_30d);
  if (f3)  parts.push(`3日 ${f3}`);
  if (f7)  parts.push(`7日 ${f7}`);
  if (f30) parts.push(`30日 ${f30}`);

  const n = Number(r.verified_count) || 0;

  out.push({
    json: {
      日期:     r.report_date,
      驗證狀態: n >= 3 ? '已完成' : `進行中 ${n}/3`,
      驗證結果: parts.length ? parts.join('｜') : '尚無資料',
    },
  });
}

console.log(`[整理 Sheets 更新] 需更新 ${out.length} 列`);
return out;
